# -*- coding: utf-8 -*-
import urllib.request, json, base64
B='http://127.0.0.1:3081'
def ex(cmd, t=300):
    r=urllib.request.Request(B+'/api/ssh/exec?token=embedded', data=json.dumps({'command':cmd}).encode(),
                             headers={'content-type':'application/json'}, method='POST')
    j=json.loads(urllib.request.urlopen(r, timeout=t).read().decode())
    return ((j.get('result') or {}).get('stdout') or '') + ((j.get('result') or {}).get('stderr') or '')
SRC = base64.b64decode("").decode('utf-8')
ex('rm -f /tmp/c6.b64 /tmp/c3shot.c')
for i in range(0, len(SRC), 800):
    ex('echo -n "%s" >> /tmp/c6.b64' % base64.b64encode(SRC[i:i+800].encode()).decode())
ex('base64 -d /tmp/c6.b64 > /tmp/c3shot.c')
print('编译:', ex('cd /tmp && gcc -O2 -I/usr/include/drm -I/usr/include/libdrm -o c3shot c3shot.c -ldrm -lgbm -lEGL -lGLESv2 2>&1|head -6; ls /tmp/c3shot >/dev/null 2>&1 && echo OK || echo FAIL')[:400])
print(ex('sudo XDG_RUNTIME_DIR=/run/user/0 /tmp/c3shot /tmp/c3shot.ppm 2>&1 | tail -8')[:900])
py2 = ('from PIL import Image' + chr(10) +
       'im=Image.open("/tmp/c3shot.ppm")' + chr(10) +
       'print("尺寸", im.size)' + chr(10) +
       'im.thumbnail((480,960))' + chr(10) +
       'im.convert("RGB").save("/tmp/c3small.jpg", quality=72)')
open('/tmp/_sm.py','w').write(py2)
cmd = 'base64 -w0 /tmp/_sm.py'
b64py = ex('echo ' + base64.b64encode(py2.encode()).decode() + ' | base64 -d > /tmp/_sm.py; echo ok').strip()
print(ex('/usr/local/venv/bin/python3 /tmp/_sm.py 2>&1 | head -3')[:300])
b64img = ex('base64 -w0 /tmp/c3small.jpg').strip()
print('  小图 base64:', len(b64img))
open('/storage/emulated/0/openpilot/c3shell/_attic/c3small.b64','w').write(b64img)

